<?php
namespace VPM\Booking;
if(!defined('ABSPATH'))exit;
final class Dashboard {
    public static function partner(int $id):array {
        Tenants::authorize($id);global $wpdb;$p=DB::row('partners','id',$id);$airport=Airports::get($p['airport']);$zone=new \DateTimeZone($airport['timezone']);$day=new \DateTimeImmutable('today',$zone);$start=$day->getTimestamp();$end=$day->modify('+1 day')->getTimestamp();
        $counts=array();$counts['requests']=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.DB::table('bookings')." WHERE partner_id=%d AND state='requested'",$id));
        foreach(array('cancellations'=>array('changes',"x.kind='cancellation' AND x.state<>'completed'"),'questions'=>array('inquiries',"x.state='pending'"),'attention'=>array('fulfilment',"x.status='attention'"),'messages'=>array('messages',"x.state='pending'"))as $key=>$spec)$counts[$key]=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.DB::table($spec[0]).' x INNER JOIN '.DB::table('bookings').' b ON b.id=x.booking_id WHERE b.partner_id=%d AND '.$spec[1],$id));
        $counts['attention']+=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.DB::table('delays')." x INNER JOIN ".DB::table('bookings')." b ON b.id=x.booking_id WHERE b.partner_id=%d AND b.state<>'cancelled' AND x.needs_review=1",$id));
        $trips=array();foreach(array('arrivals'=>"COALESCE(JSON_EXTRACT(b.snapshot,'$.partner_service.confirmed_handover_utc'),JSON_EXTRACT(b.snapshot,'$.travel.departure_utc'))",'departures'=>"COALESCE((SELECT MAX(d.collection_utc) FROM ".DB::table('delays')." d WHERE d.booking_id=b.id AND d.leg='return'),JSON_EXTRACT(b.snapshot,'$.travel.return_utc'))")as $key=>$expr){$timestamp='CAST('.$expr.' AS UNSIGNED)';$where=$wpdb->prepare(" WHERE b.partner_id=%d AND b.state='confirmed' AND b.payment_state IN ('paid','partially_refunded') AND $timestamp>=%d AND $timestamp<%d",$id,$start,$end);$counts[$key]=(int)$wpdb->get_var('SELECT COUNT(*) FROM '.DB::table('bookings').' b'.$where);$rows=$wpdb->get_results('SELECT b.public_id,'.$timestamp.' service_at FROM '.DB::table('bookings').' b'.$where.' ORDER BY service_at LIMIT 8',ARRAY_A);$trips[$key]=array_map(function($r)use($zone){return array('reference'=>$r['public_id'],'time'=>wp_date('H:i',(int)$r['service_at'],$zone));},$rows);}
        return array('counts'=>$counts,'trips'=>$trips,'date'=>$day->format('d.m.Y'),'timezone'=>$airport['timezone']);
    }
    public static function cards(array $items,string $class=''):void {echo '<div class="vpm-task-grid '.esc_attr($class).'">';foreach($items as $i)echo '<a class="vpm-task '.(!empty($i['critical'])&&$i['count']?'vpm-task-critical':'').'" href="'.esc_url($i['url']).'"><strong>'.(int)$i['count'].'</strong><span>'.esc_html($i['label']).'</span><small>'.esc_html($i['hint']??'Bereich öffnen').' →</small></a>';echo '</div>';}
    public static function render_partner(int $id):void {
        $d=self::partner($id);$c=$d['counts'];echo '<p>Heute, '.esc_html($d['date'].' · '.$d['timezone']).'. Nur bestätigte bezahlte Buchungen erscheinen als Anreisen und Abreisen.</p>';self::cards(array(array('count'=>$c['arrivals'],'label'=>'Anreisen heute','url'=>'#today','hint'=>'Übergaben ansehen'),array('count'=>$c['departures'],'label'=>'Abreisen heute','url'=>'#today','hint'=>'Abholungen ansehen'),array('count'=>$c['requests'],'label'=>'Ausstehende Anfragen','url'=>'#bookings'),array('count'=>$c['cancellations'],'label'=>'Offene Stornowünsche','url'=>'#requests','critical'=>true),array('count'=>$c['questions'],'label'=>'Kundenfragen','url'=>'#requests'),array('count'=>$c['attention'],'label'=>'Klärungsfälle','url'=>'#requests','critical'=>true),array('count'=>$c['messages'],'label'=>'Nachrichten in Plattformprüfung','url'=>'#bookings')));
        echo '<div id="today" class="vpm-today">';foreach(array('arrivals'=>'Nächste Anreisen heute','departures'=>'Nächste Abholungen heute')as $key=>$label){echo '<article><h3>'.esc_html($label).'</h3>';if(!$d['trips'][$key])echo '<p>Keine bestätigten Vorgänge für heute.</p>';foreach($d['trips'][$key]as $r)echo '<p><strong>'.esc_html($r['time']).'</strong> <a href="#bookings">'.esc_html($r['reference']).'</a></p>';echo '</article>';}echo '</div>';
    }
    public static function render_platform():void {
        Config::require(current_user_can('manage_options'),'permission_denied');global $wpdb;$url=admin_url('tools.php?page=vpm-booking-operations');self::cards(array(array('count'=>(int)$wpdb->get_var('SELECT COUNT(*) FROM '.DB::table('messages')." WHERE state='pending'"),'label'=>'Nachrichten freigeben','url'=>$url.'#communication'),array('count'=>(int)$wpdb->get_var('SELECT COUNT(*) FROM '.DB::table('profile_reviews')),'label'=>'Anfahrtsangaben prüfen','url'=>$url.'#communication'),array('count'=>(int)$wpdb->get_var('SELECT COUNT(*) FROM '.DB::table('fulfilment')." WHERE status='attention'"),'label'=>'Partnerprozesse prüfen','url'=>add_query_arg('vpm_partner_portal',1,home_url('/')),'critical'=>true),array('count'=>(int)$wpdb->get_var('SELECT COUNT(*) FROM '.DB::table('outbox')." WHERE status='attention'"),'label'=>'Versandereignisse prüfen','url'=>add_query_arg('vpm_partner_portal',1,home_url('/')),'critical'=>true)));
        echo '<p class="vpm-admin-shortcuts"><a href="'.esc_url($url.'#branding').'">Branding & Absender</a> · <a href="'.esc_url($url.'#promotions').'">Gutscheine & Aktionen</a> · <a href="'.esc_url($url.'#partners').'">Partner verwalten</a></p>';
    }
    public static function section(string $action):string {return array('services'=>'service-times','logistics'=>'logistics','logistics_refresh'=>'bookings','conditions'=>'conditions','connection'=>'connections','rate'=>'prices','capacity'=>'inventory','product'=>'products','message'=>'bookings','inquiry_done'=>'requests','delay_review'=>'requests','retry'=>'requests','cancel'=>'requests','delay'=>'requests','no_show'=>'requests')[$action]??'overview';}
}
